BEGIN;
SELECT plan(30);
UPDATE private.lifecycle_delivery_controls SET enabled=TRUE WHERE component IN ('deletion_intake','deletion_reconcile');
INSERT INTO private.billing_application_cutovers(confirmed_at,checkout_source_hash,portal_source_hash,evidence_reference)
VALUES(clock_timestamp()-INTERVAL '25 hours',repeat('a',64),repeat('b',64),'synthetic truth test');
INSERT INTO private.lifecycle_requests(user_id,state,snapshot_captured) VALUES('ba000000-0000-4000-8000-000000000001','prepared',TRUE);
INSERT INTO public.account_deletion_jobs(user_id,status,claim_token) VALUES('ba000000-0000-4000-8000-000000000001','in_progress','bb000000-0000-4000-8000-000000000001');
SELECT is(public.account_deletion_resume_stage('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'auth_delete','prepared snapshot resumes without repeating preparation');
SELECT is(public.account_deletion_resume_stage('ba000000-0000-4000-8000-000000000001',gen_random_uuid()),'lease_lost','different claim cannot resume');
SELECT ok(NOT has_function_privilege('authenticated','public.account_deletion_resume_stage(uuid,uuid)','EXECUTE'),'resume stage service only');
UPDATE private.lifecycle_requests SET snapshot_captured=FALSE WHERE user_id='ba000000-0000-4000-8000-000000000001';
SELECT is(public.account_deletion_resume_stage('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'prepare','missing snapshot cannot skip preparation');
UPDATE private.lifecycle_requests SET snapshot_captured=TRUE,state='sealed' WHERE user_id='ba000000-0000-4000-8000-000000000001';
SELECT is(public.account_deletion_resume_stage('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'prepare','sealed still needs team preparation');
UPDATE private.lifecycle_requests SET state='prepared' WHERE user_id='ba000000-0000-4000-8000-000000000001';
SELECT ok(NOT has_function_privilege('authenticated','public.begin_final_billing_verification(uuid,uuid)','EXECUTE'),'client cannot begin verification');
SELECT ok(NOT has_function_privilege('service_role','private.authorize_account_auth_delete(uuid,uuid)','EXECUTE'),'service cannot bypass final gate through old function');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'old provider completion not proof');
SELECT is(public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001')->>'status','checking','current claim starts new verification');
SELECT throws_ok($$SELECT public.reserve_provider_initiation('ba000000-0000-4000-8000-000000000001','checkout','synthetic')$$,'55000','Account deletion preparation has started','irreversible state blocks external initiation');
SELECT ok(public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'clear'),'current verification clear');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000002'),'different claim denied');
INSERT INTO private.provider_assets(user_id,provider_id) VALUES('ba000000-0000-4000-8000-000000000001','cus_synthetic_changed');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'provider-link generation invalidates clear');
SELECT public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001');
SELECT public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'clear');
SELECT public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'new lookup invalidates previous clear even before response');
SELECT ok(NOT public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',gen_random_uuid(),'clear'),'stale verification nonce rejected');
SELECT public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'provider_wait');
INSERT INTO private.provider_initiations(user_id,operation,fingerprint) VALUES('ba000000-0000-4000-8000-000000000001','portal','synthetic');
SELECT is(public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001')->>'status','provider_wait','unresolved portal blocks verification');
UPDATE private.provider_initiations SET state='reconciled' WHERE user_id='ba000000-0000-4000-8000-000000000001';
SELECT public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001');
SELECT public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'clear');
UPDATE private.final_billing_verifications SET expires_at=clock_timestamp()-INTERVAL '1 second' WHERE user_id='ba000000-0000-4000-8000-000000000001';
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'expired verification rejected');
SELECT public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001');
SELECT public.finish_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'clear');
SELECT ok(public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'stable fresh proof authorizes once');
SELECT is((SELECT state FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'consumed','authorization consumes proof');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'Auth retry requires new provider verification');
SELECT ok(NOT has_table_privilege('authenticated','private.final_billing_verifications','SELECT'),'verification state private');
SELECT ok(NOT has_function_privilege('anon','public.finish_final_billing_verification(uuid,uuid,uuid,text)','EXECUTE'),'anonymous cannot submit clear');
SELECT public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001');
SELECT ok(NOT public.preserve_final_billing_resource('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001',(SELECT token FROM private.final_billing_verifications WHERE user_id='ba000000-0000-4000-8000-000000000001'),'sub_synthetic_discovered'),'new resource invalidates current verification');
SELECT is((SELECT count(*)::INTEGER FROM private.provider_assets WHERE user_id='ba000000-0000-4000-8000-000000000001' AND provider_id='sub_synthetic_discovered'),1,'discovered identity durably preserved');
SELECT is((SELECT state FROM private.lifecycle_work WHERE user_id='ba000000-0000-4000-8000-000000000001' AND resource_id='sub_synthetic_discovered'),'received','reconcile-only discovery queues ordinary cleanup without user resubmission');
SELECT is(public.begin_final_billing_verification('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001')->>'status','provider_wait','retry sees queued obligation');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'new unresolved obligation cannot authorize Auth');
SELECT is(public.account_deletion_resume_stage('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'auth_delete','resume is not provider clearance');
SELECT ok(NOT public.authorize_account_auth_delete('ba000000-0000-4000-8000-000000000001','bb000000-0000-4000-8000-000000000001'),'resume cannot bypass unresolved provider obligation');
SELECT is(public.account_deletion_resume_stage(gen_random_uuid(),gen_random_uuid()),'lease_lost','missing job cannot resume');
SELECT * FROM finish();
ROLLBACK;
